{
  "id": "candidate-screening-v1",
  "name": "Candidate Screening Call Script v1",
  "version": "1.0.0",
  "description": "Comprehensive screening script for evaluating candidates for software engineering positions",

  "jobContext": {
    "title": "Senior Software Engineer",
    "company": "TechVentures Inc",
    "description": "Full-stack software engineer position with focus on cloud architecture and microservices",
    "location": "San Francisco, CA (Hybrid)",
    "payRange": {
      "min": 150000,
      "max": 200000
    },
    "payCurrency": "USD",
    "contractType": "Full-time",
    "duration": "Permanent",
    "schedule": "Monday-Friday, flexible hours",
    "requirements": [
      "5+ years software development experience",
      "Strong experience with cloud platforms (AWS/GCP/Azure)",
      "Proficiency in Python, Java, or Go",
      "Experience with microservices architecture",
      "Bachelor's degree in CS or equivalent experience",
      "Excellent communication skills"
    ],
    "benefits": [
      "Competitive salary and equity",
      "Health, dental, and vision insurance",
      "401k matching",
      "Flexible PTO",
      "Professional development budget"
    ],
    "metadata": {
      "team_size": 12,
      "reporting_to": "Engineering Manager",
      "interview_stages": 4,
      "urgency": "medium"
    }
  },

  "defaultAgents": {
    "greeting": {
      "agentType": "greeting",
      "name": "Professional Screener",
      "description": "Professional greeting and introduction",
      "instructions": "Be professional and friendly. Set expectations for the call. Build rapport quickly.",
      "voiceProfileId": "professional",
      "personalityTraits": ["professional", "friendly", "organized"],
      "capabilities": ["rapport_building", "expectation_setting"],
      "tools": ["calendar_check", "candidate_profile"]
    },
    "qualifier": {
      "agentType": "qualifier",
      "name": "Technical Screener",
      "description": "Evaluates technical qualifications and experience",
      "instructions": "Ask probing technical questions. Assess depth of knowledge. Take detailed notes.",
      "voiceProfileId": "professional",
      "personalityTraits": ["analytical", "thorough", "curious"],
      "capabilities": [
        "technical_assessment",
        "experience_validation",
        "skill_evaluation"
      ],
      "tools": ["skill_matcher", "experience_calculator", "note_taker"]
    },
    "information": {
      "agentType": "information",
      "name": "Role Presenter",
      "description": "Provides detailed information about the role and company",
      "instructions": "Present the opportunity enthusiastically. Highlight growth potential. Answer questions thoroughly.",
      "voiceProfileId": "enthusiastic",
      "personalityTraits": ["enthusiastic", "informative", "transparent"],
      "capabilities": [
        "opportunity_presentation",
        "company_culture_description"
      ],
      "tools": ["company_info", "team_details"]
    },
    "confirmation": {
      "agentType": "confirmation",
      "name": "Details Confirmer",
      "description": "Confirms key information and next steps",
      "instructions": "Verify all critical information. Confirm mutual interest. Set clear next steps.",
      "voiceProfileId": "professional",
      "personalityTraits": ["precise", "organized", "clear"],
      "capabilities": ["information_verification", "schedule_coordination"],
      "tools": ["calendar_system", "confirmation_sender"]
    },
    "closer": {
      "agentType": "closer",
      "name": "Professional Closer",
      "description": "Professionally concludes the screening call",
      "instructions": "Summarize key points. Set expectations for timeline. Thank them professionally.",
      "voiceProfileId": "professional",
      "personalityTraits": ["professional", "courteous", "clear"],
      "capabilities": ["summary_generation", "timeline_communication"],
      "tools": ["email_sender", "ats_updater"]
    }
  },

  "voiceProfiles": {
    "professional": {
      "voiceId": "voice-prof-002",
      "name": "Professional Recruiter Voice",
      "language": "en-US",
      "pitch": 1.0,
      "speed": 1.0,
      "personalityTraits": ["professional", "confident", "articulate"]
    },
    "enthusiastic": {
      "voiceId": "voice-enth-002",
      "name": "Enthusiastic Presenter Voice",
      "language": "en-US",
      "pitch": 1.05,
      "speed": 1.05,
      "emotion": "enthusiastic",
      "personalityTraits": ["energetic", "passionate", "engaging"]
    },
    "empathetic": {
      "voiceId": "voice-emp-002",
      "name": "Empathetic Listener Voice",
      "language": "en-US",
      "pitch": 0.98,
      "speed": 0.95,
      "emotion": "understanding",
      "personalityTraits": ["patient", "understanding", "supportive"]
    }
  },

  "defaultVoiceProfileId": "professional",
  "startNodeId": "greeting",

  "callConfig": {
    "recording_enabled": true,
    "transcription_enabled": true,
    "sentiment_analysis_enabled": true,
    "technical_assessment_enabled": true,
    "ats_integration_enabled": true
  },

  "globalTimeoutSeconds": 2700,
  "maxConversationTurns": 60,

  "initialContext": {
    "company": "TechVentures Inc",
    "position": "Senior Software Engineer",
    "recruiter_name": "Sarah",
    "interview_duration": "30-45 minutes"
  },

  "nodes": [
    {
      "id": "greeting",
      "title": "Professional Greeting",
      "initiationText": "Hi {first_name}, this is {recruiter_name} from {company}. Thank you for taking my call! I'm calling about the {position} role you applied for. This is a screening call that should take about {interview_duration}. Is now still a good time to talk?",
      "agentType": "greeting",
      "greenPath": {
        "targetNodeId": "confirm-interest",
        "description": "Candidate ready to proceed"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "end-not-available"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 30,
      "isTerminal": false,
      "dataPoints": [],
      "requiredContext": [
        "first_name",
        "recruiter_name",
        "company",
        "position"
      ],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "confirm-interest",
      "title": "Confirm Interest Level",
      "prompt": "Great! Before we dive in, I want to make sure this opportunity aligns with what you're looking for. What interested you most about this position when you applied?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "current-situation",
        "description": "Strong interest expressed"
      },
      "yellowPaths": [
        {
          "targetNodeId": "clarify-role",
          "condition": "unclear_about_role",
          "description": "Needs role clarification",
          "onResolve": "return-to-green"
        }
      ],
      "redPath": {
        "targetNodeId": "end-not-interested"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 1,
      "timeoutSeconds": 45,
      "isTerminal": false,
      "dataPoints": [],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "current-situation",
      "title": "Current Employment Status",
      "prompt": "That's great to hear! Can you tell me about your current role and what you're doing day-to-day?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "years-experience",
        "description": "Described current role"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "system-error"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 90,
      "isTerminal": false,
      "dataPoints": [
        "current_role",
        "current_company",
        "current_responsibilities"
      ],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true,
        "allow_detailed_response": true
      }
    },

    {
      "id": "years-experience",
      "title": "Total Experience Verification",
      "prompt": "How many years of professional software development experience do you have in total?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "technical-experience",
        "description": "Meets experience requirement"
      },
      "yellowPaths": [
        {
          "targetNodeId": "relevant-experience",
          "condition": "less_than_required",
          "description": "Less than 5 years",
          "onResolve": "move-forward"
        }
      ],
      "redPath": {
        "targetNodeId": "end-insufficient-experience"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 30,
      "isTerminal": false,
      "dataPoints": ["total_years_experience"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "technical-experience",
      "title": "Technical Stack Assessment",
      "prompt": "Excellent! This role requires strong experience with cloud platforms and microservices. Can you tell me about your experience with AWS, GCP, or Azure, and any microservices architectures you've worked with?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "programming-languages",
        "description": "Has relevant cloud experience"
      },
      "yellowPaths": [
        {
          "targetNodeId": "alternative-tech",
          "condition": "different_tech_stack",
          "description": "Different but relevant tech",
          "onResolve": "move-forward"
        }
      ],
      "redPath": {
        "targetNodeId": "technical-mismatch"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 120,
      "isTerminal": false,
      "dataPoints": [
        "cloud_experience",
        "microservices_experience",
        "architecture_knowledge"
      ],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true,
        "technical_evaluation": true
      }
    },

    {
      "id": "programming-languages",
      "title": "Programming Language Proficiency",
      "prompt": "The team primarily works with Python, Java, and Go. Which of these are you most proficient in, and can you describe a recent project where you used it?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "project-example",
        "description": "Strong language match"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "technical-mismatch"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 90,
      "isTerminal": false,
      "dataPoints": [
        "primary_language",
        "language_proficiency",
        "project_description"
      ],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true,
        "technical_evaluation": true
      }
    },

    {
      "id": "project-example",
      "title": "Detailed Project Discussion",
      "prompt": "That sounds interesting! Can you walk me through the technical challenges you faced in that project and how you solved them?",
      "agentType": "qualifier",
      "agentOverride": {
        "instructions": "Listen for problem-solving skills, technical depth, and communication clarity. Ask follow-up questions if needed.",
        "personalityTraits": ["curious", "analytical", "engaged"]
      },
      "greenPath": {
        "targetNodeId": "team-collaboration",
        "description": "Good technical demonstration"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "technical-concerns"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 1,
      "timeoutSeconds": 150,
      "isTerminal": false,
      "dataPoints": [
        "technical_challenges",
        "problem_solving",
        "technical_depth"
      ],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true,
        "allow_extended_time": true,
        "technical_evaluation": true
      }
    },

    {
      "id": "team-collaboration",
      "title": "Team and Communication Skills",
      "prompt": "How do you typically collaborate with other engineers and stakeholders? Can you give me an example of a time when you had to explain a complex technical concept to non-technical team members?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "salary-expectations",
        "description": "Good communication skills"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "communication-concerns"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 90,
      "isTerminal": false,
      "dataPoints": [
        "collaboration_style",
        "communication_example",
        "stakeholder_management"
      ],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "salary-expectations",
      "title": "Compensation Discussion",
      "prompt": "Before we continue, I want to make sure we're aligned on compensation. The range for this position is ${min} to ${max} per year, depending on experience. Does that align with your expectations?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "work-authorization",
        "description": "Salary aligned"
      },
      "yellowPaths": [
        {
          "targetNodeId": "negotiate-range",
          "condition": "higher_expectations",
          "description": "Expects higher salary",
          "onResolve": "move-forward"
        }
      ],
      "redPath": {
        "targetNodeId": "end-salary-mismatch"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 45,
      "isTerminal": false,
      "dataPoints": ["salary_expectations", "current_compensation"],
      "requiredContext": ["min", "max"],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "work-authorization",
      "title": "Work Authorization Check",
      "prompt": "Are you legally authorized to work in the United States? Will you require sponsorship now or in the future?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "location-preference",
        "description": "Authorized to work"
      },
      "yellowPaths": [
        {
          "targetNodeId": "visa-details",
          "condition": "requires_sponsorship",
          "description": "Needs sponsorship",
          "onResolve": "move-forward"
        }
      ],
      "redPath": {
        "targetNodeId": "end-authorization-issue"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 30,
      "isTerminal": false,
      "dataPoints": ["work_authorization_status", "sponsorship_needs"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "location-preference",
      "title": "Location and Remote Work",
      "prompt": "This position is hybrid in San Francisco, requiring 2-3 days per week in the office. Are you currently in the Bay Area or willing to relocate?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "availability-timeline",
        "description": "Location works"
      },
      "yellowPaths": [
        {
          "targetNodeId": "remote-negotiation",
          "condition": "wants_full_remote",
          "description": "Prefers full remote",
          "onResolve": "move-forward"
        }
      ],
      "redPath": {
        "targetNodeId": "end-location-mismatch"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 2,
      "timeoutSeconds": 45,
      "isTerminal": false,
      "dataPoints": [
        "current_location",
        "relocation_willingness",
        "remote_preference"
      ],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "availability-timeline",
      "title": "Start Date Availability",
      "prompt": "When would you be available to start if an offer were extended? Do you have any notice period with your current employer?",
      "agentType": "qualifier",
      "greenPath": {
        "targetNodeId": "role-presentation",
        "description": "Reasonable timeline"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "timeline-concerns"
      },
      "requirementLevel": "preferred",
      "maxRetries": 1,
      "timeoutSeconds": 45,
      "isTerminal": false,
      "dataPoints": ["availability_date", "notice_period"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "role-presentation",
      "title": "Detailed Role Presentation",
      "prompt": "Let me tell you more about the role and team. You'd be joining a team of 12 engineers working on our core platform. The focus is on building scalable microservices that handle millions of transactions daily. The tech stack includes Python and Go, with infrastructure on AWS using Kubernetes. You'd report to our Engineering Manager and have opportunities to lead technical initiatives. Does this sound like something that excites you?",
      "agentType": "information",
      "greenPath": {
        "targetNodeId": "candidate-questions",
        "description": "Interested in role"
      },
      "yellowPaths": [
        {
          "targetNodeId": "address-concerns",
          "condition": "has_concerns",
          "description": "Has concerns",
          "onResolve": "return-to-green"
        }
      ],
      "redPath": {
        "targetNodeId": "not-good-fit"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 1,
      "timeoutSeconds": 90,
      "isTerminal": false,
      "dataPoints": ["role_interest_level"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "candidate-questions",
      "title": "Answer Candidate Questions",
      "prompt": "What questions do you have about the role, team, or company?",
      "agentType": "information",
      "agentOverride": {
        "instructions": "Answer questions thoroughly and honestly. If you don't know something, offer to find out and follow up.",
        "personalityTraits": ["helpful", "transparent", "informative"]
      },
      "greenPath": {
        "targetNodeId": "next-steps",
        "description": "Questions answered"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "too-many-concerns"
      },
      "requirementLevel": "preferred",
      "maxRetries": 3,
      "timeoutSeconds": 180,
      "isTerminal": false,
      "dataPoints": ["candidate_questions", "question_responses"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true,
        "allow_multiple_questions": true
      }
    },

    {
      "id": "next-steps",
      "title": "Explain Next Steps",
      "prompt": "Based on our conversation, I think you could be a great fit for this role! The next step would be a technical phone screen with one of our senior engineers, which would be about an hour and include some coding exercises. After that, there would be an onsite interview with the team. Are you interested in moving forward?",
      "agentType": "confirmation",
      "greenPath": {
        "targetNodeId": "schedule-next",
        "description": "Wants to proceed"
      },
      "yellowPaths": [
        {
          "targetNodeId": "think-about-it",
          "condition": "needs_time",
          "description": "Needs time to think",
          "onResolve": "move-forward"
        }
      ],
      "redPath": {
        "targetNodeId": "end-not-proceeding"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 1,
      "timeoutSeconds": 45,
      "isTerminal": false,
      "dataPoints": ["proceed_decision"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "schedule-next",
      "title": "Schedule Technical Screen",
      "prompt": "Excellent! What days and times generally work best for you for the technical phone screen? I have availability this week and next week.",
      "agentType": "confirmation",
      "greenPath": {
        "targetNodeId": "confirm-details",
        "description": "Availability provided"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "follow-up-scheduling"
      },
      "requirementLevel": "preferred",
      "maxRetries": 2,
      "timeoutSeconds": 60,
      "isTerminal": false,
      "dataPoints": ["availability_windows", "timezone"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "confirm-details",
      "title": "Confirm Contact Information",
      "prompt": "Perfect! Let me confirm your contact information. Is {email} still the best email to reach you? And is {phone} your preferred phone number?",
      "agentType": "confirmation",
      "greenPath": {
        "targetNodeId": "successful-close",
        "description": "Info confirmed"
      },
      "yellowPaths": [
        {
          "targetNodeId": "update-contact",
          "condition": "info_changed",
          "description": "Update needed",
          "onResolve": "return-to-green"
        }
      ],
      "redPath": {
        "targetNodeId": "system-error"
      },
      "requirementLevel": "mandatory",
      "maxRetries": 1,
      "timeoutSeconds": 30,
      "isTerminal": false,
      "dataPoints": ["email_confirmed", "phone_confirmed"],
      "requiredContext": ["email", "phone"],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "successful-close",
      "title": "Successful Screening Close",
      "prompt": "Wonderful, {first_name}! I really enjoyed our conversation today. You'll receive an email within the next hour with the technical screen details and some preparation materials. The email will also include my contact information if you have any questions before then. Thank you so much for your time, and I look forward to the next steps!",
      "agentType": "closer",
      "greenPath": null,
      "yellowPaths": [],
      "redPath": null,
      "requirementLevel": "optional",
      "maxRetries": 0,
      "timeoutSeconds": 20,
      "isTerminal": true,
      "dataPoints": [],
      "requiredContext": ["first_name"],
      "metadata": {
        "shouldRecordResponse": false,
        "triggers_email": true,
        "update_ats": true,
        "screening_result": "passed"
      }
    },

    {
      "id": "not-good-fit",
      "title": "Not a Good Fit",
      "prompt": "Based on our discussion, I don't think this particular role is the perfect match for your background and interests. However, we have other positions that might be a better fit. Would you be open to me reaching out if something more aligned comes up?",
      "agentType": "closer",
      "agentOverride": {
        "voiceProfileId": "empathetic",
        "instructions": "Be kind and professional. Leave the door open for future opportunities.",
        "personalityTraits": ["empathetic", "professional", "encouraging"]
      },
      "greenPath": null,
      "yellowPaths": [],
      "redPath": null,
      "requirementLevel": "optional",
      "maxRetries": 0,
      "timeoutSeconds": 30,
      "isTerminal": true,
      "dataPoints": ["keep_in_pipeline"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true,
        "update_ats": true,
        "screening_result": "not_qualified"
      }
    },

    {
      "id": "reschedule",
      "title": "Reschedule Screening",
      "prompt": "No problem at all! When would be a better time for you? I have availability throughout this week and next week.",
      "agentType": "confirmation",
      "greenPath": {
        "targetNodeId": "reschedule-confirmed",
        "description": "New time agreed"
      },
      "yellowPaths": [],
      "redPath": {
        "targetNodeId": "follow-up-later"
      },
      "requirementLevel": "preferred",
      "maxRetries": 2,
      "timeoutSeconds": 45,
      "isTerminal": false,
      "dataPoints": ["reschedule_time", "reschedule_date"],
      "requiredContext": [],
      "metadata": {
        "shouldRecordResponse": true
      }
    },

    {
      "id": "reschedule-confirmed",
      "title": "Confirm Reschedule",
      "prompt": "Perfect! I've scheduled our screening call for {reschedule_date} at {reschedule_time}. You'll receive a calendar invitation shortly. Looking forward to speaking with you then!",
      "agentType": "closer",
      "greenPath": null,
      "yellowPaths": [],
      "redPath": null,
      "requirementLevel": "optional",
      "maxRetries": 0,
      "timeoutSeconds": 15,
      "isTerminal": true,
      "dataPoints": [],
      "requiredContext": ["reschedule_date", "reschedule_time"],
      "metadata": {
        "shouldRecordResponse": false,
        "triggers_calendar": true
      }
    },

    {
      "id": "end-not-interested",
      "title": "Candidate Not Interested",
      "prompt": "I understand, and I appreciate your honesty. Thank you for your time today. If your situation changes or you see other roles at {company} that interest you, please don't hesitate to reach out. Best of luck with your search!",
      "agentType": "closer",
      "greenPath": null,
      "yellowPaths": [],
      "redPath": null,
      "requirementLevel": "optional",
      "maxRetries": 0,
      "timeoutSeconds": 15,
      "isTerminal": true,
      "dataPoints": [],
      "requiredContext": ["company"],
      "metadata": {
        "shouldRecordResponse": false,
        "update_ats": true,
        "screening_result": "not_interested"
      }
    },

    {
      "id": "end-insufficient-experience",
      "title": "Insufficient Experience",
      "prompt": "Thank you for your time today. While your background is impressive, we're looking for someone with a bit more experience for this senior role. However, I'd love to keep your information on file for future opportunities that might be a better match. Would that be okay with you?",
      "agentType": "closer",
      "agentOverride": {
        "voiceProfileId": "empathetic",
        "personalityTraits": ["encouraging", "professional", "respectful"]
      },
      "greenPath": null,
      "yellowPaths": [],
      "redPath": null,
      "requirementLevel": "optional",
      "maxRetries": 0,
