  "context": {
    "job_position": {
      "title": "IT Call Support Operator",
      "description": "Provide technical support to customers via phone, chat, and email. Troubleshoot hardware and software issues, document incidents, and ensure customer satisfaction.",
      "company": "TechSupport Solutions Inc.",
      "client": null,
      "location": "Remote (USA)",
      "pay": {
        "range": {
          "min": 18.00,
          "max": 28.00
        },
        "currency": "USD",
        "frequency": "hourly"
      },
      "contract_type": "W2",
      "duration": "Full-time",
      "start_date": "Immediate",
      "schedule": "Rotating shifts, including evenings and weekends",
      "requirements": [
        "2+ years of IT support or helpdesk experience",
        "Strong knowledge of Windows and Mac OS",
        "Experience with ticketing systems",
        "Excellent verbal and written communication skills",
        "Ability to work independently",
        "High school diploma or equivalent"
      ],
      "benefits": [
        "Health and dental insurance",
        "401k matching",
        "Paid time off",
        "Remote work setup stipend",
        "Training and certification opportunities"
      ],
      "metadata": {
        "team_size": 25,
        "reporting_to": "Support Team Lead",
        "urgency": "high",
        "positions_available": 5
      },
      "additional_data": {}
    },
    "initial_candidate_context": {}
  },

  "starting_node": "greeting_node",

  "call_nodes": {
    "greeting_node": {
      "id": "greeting_node",
      "title": "Initial Greeting",
      "description": "Greet the candidate and confirm they're ready for the interview",
      "initial_message": "Hello! This is the automated hiring assistant from TechSupport Solutions. I'm calling about your application for the IT Call Support Operator position. Is this a good time to conduct a brief screening interview? It should take about 15-20 minutes.",
      "agent_type": "greeting",
      "on_success": {
        "next_node_id": "experience_qualification",
        "description": "Candidate is ready to proceed"
      },
      "failure_handling": [
        {
          "failure_reason": "Candidate not available",
          "behavior": "SKIP",
          "next_node_id": "reschedule_node"
        }
      ]
    },

    "experience_qualification": {
      "id": "experience_qualification",
      "title": "IT Support Experience",
      "description": "Assess candidate's IT support experience",
      "initial_message": "Great! Let's start with your experience. How many years have you worked in IT support or helpdesk roles?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "years_of_it_support_experience",
          "description": "Total years of experience in IT support or helpdesk roles"
        }
      ],
      "on_success": {
        "next_node_id": "ticketing_systems",
        "description": "Experience captured"
      },
      "post_requisites": [
        {
          "strategy": "DATAPOINT_QUERY",
          "query": "years_of_it_support_experience.value >= 1"
        }
      ],
      "failure_handling": [
        {
          "failure_reason": "Insufficient experience",
          "behavior": "SKIP",
          "next_node_id": "insufficient_experience_close"
        }
      ]
    },

    "ticketing_systems": {
      "id": "ticketing_systems",
      "title": "Ticketing Systems Experience",
      "description": "Identify ticketing systems experience",
      "initial_message": "Excellent! Which ticketing systems have you worked with? For example, ServiceNow, Zendesk, Jira Service Desk, or others?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "ticketing_systems_used",
          "description": "List of ticketing systems the candidate has experience with"
        }
      ],
      "on_success": {
        "next_node_id": "technical_skills",
        "description": "Ticketing systems captured"
      }
    },

    "technical_skills": {
      "id": "technical_skills",
      "title": "Technical Certifications",
      "description": "Assess technical certifications and skills",
      "initial_message": "Do you hold any IT certifications such as CompTIA A+, Network+, ITIL, or Microsoft certifications?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "technical_certifications",
          "description": "IT certifications held by the candidate"
        }
      ],
      "on_success": {
        "next_node_id": "remote_tools",
        "description": "Certifications noted"
      }
    },

    "remote_tools": {
      "id": "remote_tools",
      "title": "Remote Support Tools",
      "description": "Verify experience with remote support",
      "initial_message": "This role involves remote troubleshooting. Do you have experience using remote desktop tools like TeamViewer, LogMeIn, or Windows Remote Desktop?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "remote_troubleshooting_experience",
          "description": "Experience with remote desktop and troubleshooting tools"
        }
      ],
      "on_success": {
        "next_node_id": "customer_service",
        "description": "Remote experience confirmed"
      }
    },

    "customer_service": {
      "id": "customer_service",
      "title": "Customer Service Skills",
      "description": "Evaluate customer service capabilities",
      "initial_message": "Customer service is crucial for this role. On a scale of 1 to 10, how would you rate your customer service skills? Can you briefly describe a challenging customer situation you've handled?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "customer_service_rating",
          "description": "Self-assessed customer service skills rating"
        }
      ],
      "on_success": {
        "next_node_id": "language_skills",
        "description": "Customer service assessed"
      },
      "post_requisites": [
        {
          "strategy": "DATAPOINT_QUERY",
          "query": "customer_service_rating.value >= 7"
        }
      ]
    },

    "language_skills": {
      "id": "language_skills",
      "title": "Language Capabilities",
      "description": "Identify language skills",
      "initial_message": "What languages can you provide support in? Please list all languages you're fluent in.",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "languages_spoken",
          "description": "Languages the candidate can provide support in"
        }
      ],
      "on_success": {
        "next_node_id": "shift_availability",
        "description": "Languages documented"
      }
    },

    "shift_availability": {
      "id": "shift_availability",
      "title": "Schedule Availability",
      "description": "Confirm shift availability",
      "initial_message": "This position requires rotating shifts. Are you available to work morning shifts, evening shifts, night shifts, and weekends? Please let me know which shifts work for you.",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "shift_availability",
          "description": "Available shifts the candidate can work"
        }
      ],
      "on_success": {
        "next_node_id": "home_office",
        "description": "Availability confirmed"
      }
    },

    "home_office": {
      "id": "home_office",
      "title": "Home Office Setup",
      "description": "Verify home office readiness",
      "initial_message": "Since this is a remote position, do you have a quiet workspace with reliable internet connection and a computer suitable for work?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "has_home_office_setup",
          "description": "Whether candidate has proper home office setup for remote work"
        }
      ],
      "on_success": {
        "next_node_id": "salary_expectations",
        "description": "Home office confirmed"
      },
      "post_requisites": [
        {
          "strategy": "DATAPOINT_QUERY",
          "query": "has_home_office_setup.value = true"
        }
      ],
      "failure_handling": [
        {
          "failure_reason": "No home office setup",
          "behavior": "SKIP",
          "next_node_id": "setup_discussion"
        }
      ]
    },

    "salary_expectations": {
      "id": "salary_expectations",
      "title": "Compensation Discussion",
      "description": "Discuss salary expectations",
      "initial_message": "The hourly rate for this position ranges from $18 to $28 per hour, depending on experience. What is your expected hourly rate?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "expected_hourly_rate",
          "description": "Expected hourly rate in USD"
        }
      ],
      "on_success": {
        "next_node_id": "start_date",
        "description": "Salary aligned"
      },
      "post_requisites": [
        {
          "strategy": "DATAPOINT_QUERY",
          "query": "expected_hourly_rate.value <= 30"
        }
      ]
    },

    "start_date": {
      "id": "start_date",
      "title": "Availability to Start",
      "description": "Confirm start date",
      "initial_message": "When would you be available to start if selected for this position?",
      "agent_type": "qualifier",
      "datapoints_to_collect": [
        {
          "key": "availability_start_date",
          "description": "When the candidate can start working"
        }
      ],
      "on_success": {
        "next_node_id": "role_information",
        "description": "Start date captured"
      }
    },

    "role_information": {
      "id": "role_information",
      "title": "Role Details",
      "description": "Provide detailed information about the role",
      "initial_message": "Let me give you more details about the position. You'll be handling 40-50 support tickets daily, providing phone and chat support for software and hardware issues. We offer comprehensive training, health benefits, 401k matching, and opportunities for certifications. The team is supportive and we promote from within. Do you have any questions about the role?",
      "agent_type": "information",
      "on_success": {
        "next_node_id": "next_steps",
        "description": "Information provided"
      }
    },

    "next_steps": {
      "id": "next_steps",
      "title": "Next Steps",
      "description": "Explain the next steps in the process",
      "initial_message": "Based on our conversation, you seem like a great fit! The next step would be a technical assessment and a video interview with the team lead. We'll send you an email with the assessment link and available interview slots. Are you interested in moving forward?",
      "agent_type": "information",
      "on_success": {
        "next_node_id": "successful_close",
        "description": "Candidate wants to proceed"
      },
      "failure_handling": [
        {
          "failure_reason": "Not interested",
          "behavior": "SKIP",
          "next_node_id": "polite_decline_close"
        }
      ]
    },

    "successful_close": {
      "id": "successful_close",
      "title": "Successful Close",
      "description": "Successfully close the screening call",
      "initial_message": "Excellent! You'll receive an email within the next hour with all the details. Thank you for your time today, and we look forward to the next steps in the process. Have a great day!",
      "agent_type": "closer",
      "on_success": null
    },

    "insufficient_experience_close": {
      "id": "insufficient_experience_close",
      "title": "Insufficient Experience Close",
      "description": "Politely close for candidates with insufficient experience",
      "initial_message": "Thank you for your interest in this position. We're currently looking for candidates with at least 2 years of IT support experience. However, we'll keep your application on file for future entry-level positions. We appreciate your time today!",
      "agent_type": "closer",
      "on_success": null
    },

    "polite_decline_close": {
      "id": "polite_decline_close",
      "title": "Candidate Declined Close",
      "description": "Close when candidate is not interested",
      "initial_message": "I understand and appreciate your honesty. Thank you for taking the time to speak with us today. If you change your mind or see other positions that interest you, please don't hesitate to apply. Best of luck in your job search!",
      "agent_type": "closer",
      "on_success": null
    },

    "reschedule_node": {
      "id": "reschedule_node",
      "title": "Reschedule Interview",
      "description": "Reschedule the screening interview",
      "initial_message": "No problem at all! When would be a better time for you? We have availability throughout this week and next week.",
      "agent_type": "information",
      "on_success": {
        "next_node_id": "reschedule_close",
        "description": "Time rescheduled"
      }
    },

    "reschedule_close": {
      "id": "reschedule_close",
      "title": "Reschedule Confirmation",
      "description": "Confirm the rescheduled time",
      "initial_message": "Perfect! We'll call you at the scheduled time. You'll also receive an email confirmation. Thank you and speak to you soon!",
      "agent_type": "closer",
      "on_success": null
    },

    "setup_discussion": {
      "id": "setup_discussion",
      "title": "Home Office Setup Discussion",
      "description": "Discuss home office requirements",
      "initial_message": "We provide a setup stipend to help you create a suitable home office. Would you be able to set up a proper workspace if we provide the necessary support?",
      "agent_type": "information",
      "on_success": {
        "next_node_id": "salary_expectations",
        "description": "Setup discussion complete"
      }
    }
  }
}

